/** A database level of the Black Snake, his pinned native tree, the templates, the projectile and the clips. */
export function blackSnakeNative(r,n){
 const lv=LEVELS[r?.level];
 if(!isBlackSnake(r)||!lv||r.key!==r.prefabKey||r.notCountInTotal||r.applyWay!==SPEC.applyWay||Object.entries(lv.stats).some(([k,v])=>!same(r.stats[k],v))
  ||!same(r.abilities,SPEC.abilities)||!same(databaseTalents(r),lv.talents)||!same(r.skills,lv.skills))return false;
 if(!same(closure(n),SPEC.components)||Object.entries(TEMPLATES).some(([k,v])=>!same(n.$template(k),v))
  ||Object.entries(PROJECTILES).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v)))return false;
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=clocks.enemies[r.prefabKey];
 return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
  &&Object.entries(CLOCK.durations).every(([k,v])=>clock.durations[k]===v)
  &&Object.entries(CLOCK.events).every(([k,v])=>same(clock.events[k]?.filter(x=>x.name==="OnAttack").map(x=>x.time),v));
}
// The stage's hint.location / hint.interval are injected presentation parameters; the rest must be the database's.
function databaseTalents(r){
 const bb={...r.talents?.bb},bbStr={...r.talents?.bbStr},groups=structuredClone(r.talents?.groups??{});
 delete bb["hint.interval"];delete bbStr["hint.location"];
 if(groups.hint){groups.hint=groups.hint.filter(k=>!["interval","location"].includes(k));if(!groups.hint.length)delete groups.hint;}
 return {bb,bbStr,groups};
}
